using System;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using Bodu.Extensions;
using System.Globalization;

namespace Bodu.Extensions;

public partial class DateOnlyExtensionsTests
{

    /// <summary>
    /// Verifies that <see cref="DateOnlyExtensions.PreviousDateOfWeek(DateOnly, DayOfWeek)" /> returns the prior occurrence of the requested <see cref="DayOfWeek" /> for each <c>(input, target)</c> pair.
    /// </summary>
    [TestMethod]
    [DynamicData(nameof(DateTimeExtensionsTests.PreviousDateOfWeekTestData), typeof(DateTimeExtensionsTests))]
    public void PreviousDateOfWeek_WhenCalled_ShouldReturnExpectedDate(DateTime inputDateOnly, DayOfWeek targetDay, DateTime expectedDateOnly)
    {
        var input = DateOnly.FromDateTime(inputDateOnly);
        var expected = DateOnly.FromDateTime(expectedDateOnly);

        var actual = input.PreviousDateOfWeek(targetDay);

        Assert.AreEqual(expected, actual);
    }

    /// <summary>
    /// Verifies that an undefined <see cref="DayOfWeek" /> value throws <see cref="ArgumentOutOfRangeException" />.
    /// </summary>
    [TestMethod]
    public void PreviousDateOfWeek_WhenEnumIsInvalid_ShouldThrowExactly()
    {
        var input = new DateOnly(2024, 4, 18);

        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() =>
        {
            _ = input.PreviousDateOfWeek((DayOfWeek)999);
        });
    }

    /// <summary>
    /// Verifies that <see cref="DateOnly.MinValue" /> + 7 days returning the prior Monday yields a result on or after <see cref="DateOnly.MinValue" />.
    /// </summary>
    [TestMethod]
    public void PreviousDateOfWeek_WhenUsingMinValue_ShouldReturnSameOrGreater()
    {
        var actual = DateOnly.MinValue.AddDays(7).PreviousDateOfWeek(DayOfWeek.Monday);

        Assert.IsTrue(actual >= DateOnly.MinValue);
    }

    /// <summary>
    /// Verifies that <see cref="DateOnly.MaxValue" /> targeting Saturday returns a valid result on or before <see cref="DateOnly.MaxValue" />.
    /// </summary>
    [TestMethod]
    public void PreviousDateOfWeek_WhenUsingMaxValue_ShouldSucceed()
    {
        var input = DateOnly.MaxValue;
        var actual = input.PreviousDateOfWeek(DayOfWeek.Saturday);

        Assert.IsTrue(actual <= DateOnly.MaxValue);
    }
}
